#!/usr/bin/env node
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const checkOnly = process.argv.includes("--check");
const PATCH = "TIBIAGAME_V36_64_0_COMPACT_UI_ROOF_DEPTH";

function fail(message) {
  console.error(`\n${PATCH} FAILED: ${message}`);
  process.exit(1);
}

function replaceOnce(source, before, after, label) {
  const first = source.indexOf(before);
  if (first < 0) {
    if (source.includes(after)) return source;
    fail(`Could not find expected source for ${label}. Repository is not at the expected V36.63.0 baseline.`);
  }
  if (source.indexOf(before, first + before.length) >= 0) {
    fail(`Expected source for ${label} occurs more than once; refusing an ambiguous patch.`);
  }
  return source.slice(0, first) + after + source.slice(first + before.length);
}

function replaceBlock(source, startMarker, endMarker, replacement, label) {
  const start = source.indexOf(startMarker);
  if (start < 0) {
    fail(`Could not find start marker for ${label}. Repository is not at the expected V36.63.0 baseline.`);
  }
  const duplicateStart = source.indexOf(startMarker, start + startMarker.length);
  if (duplicateStart >= 0) {
    fail(`Start marker for ${label} occurs more than once; refusing an ambiguous patch.`);
  }
  const end = source.indexOf(endMarker, start + startMarker.length);
  if (end < 0) {
    fail(`Could not find end marker for ${label}.`);
  }
  return source.slice(0, start) + replacement + "\n\n" + source.slice(end);
}

function patchFile(relativePath, transform) {
  const path = join(root, relativePath);
  let source;
  try {
    source = readFileSync(path, "utf8");
  } catch (error) {
    fail(`Cannot read ${relativePath}: ${error.message}`);
  }

  if (source.includes(`// ${PATCH}`)) {
    console.log(`Already patched: ${relativePath}`);
    return false;
  }

  const next = transform(source);
  if (next === source) {
    fail(`Patch produced no changes for ${relativePath}.`);
  }

  if (!checkOnly) {
    writeFileSync(path, next, "utf8");
  }
  return true;
}

console.log(PATCH);
console.log(checkOnly ? "Mode: precheck only" : "Mode: apply");

